const rows = $('New breaches').all().map((i) => i.json);
const lines = rows.map((r) => '- ' + r.email + ': ' + r.breach + ' (' + r.breach_date + ')' + (r.passwords ? ' [PASSWORDS EXPOSED]' : '') + '\n  Data: ' + r.data);
return [{ json: { count: rows.length, people: new Set(rows.map((r) => r.email)).size, passwords: rows.filter((r) => r.passwords).length, text: lines.join('\n') }, pairedItem: rows.map((_, i) => ({ item: i })) }];

